/**
 * Deduplicates an array of Judgement items by unique ID.
 * Keeps the first occurrence of each unique ID.
 */
export function deduplicateJudgements(judgements: Judgement[]): Judgement[] {
  const seenIds = new Set<string>();
  return judgements.filter((j) => {
    if (!j.id || seenIds.has(j.id)) {
      return false;
    }
    seenIds.add(j.id);
    return true;
  });
}

/**
 * Exported MASTER_JUDGEMENTS array, initialized without duplicates.
 */
export const MASTER_JUDGEMENTS: Judgement[] = deduplicateJudgements(RAW_MASTER_JUDGEMENTS);

/**
 * Updates the exported MASTER_JUDGEMENTS array with additional judgments,
 * filtering out any duplicates based on ID.
 *
 * @param newJudgements Array of Judgement items to merge into MASTER_JUDGEMENTS
 * @returns Updated and deduplicated MASTER_JUDGEMENTS array
 */
export function updateMasterJudgements(newJudgements: Judgement[]): Judgement[] {
  const combined = [...MASTER_JUDGEMENTS, ...newJudgements];
  const deduplicated = deduplicateJudgements(combined);
  
  MASTER_JUDGEMENTS.length = 0;
  MASTER_JUDGEMENTS.push(...deduplicated);
  
  return MASTER_JUDGEMENTS;
}




